#include <vector>
#include <iostream>

int main() {
    std::vector<int> v = {10, 20, 30, 40};
    auto it_30 = v.begin() + 2; // Iterator pointing to 30
    auto it_40 = v.begin() + 3; // Iterator pointing to 40

    // Erase the element 30
    auto next_it = v.erase(it_30); 

    // next_it is safe (points to the element that was 40)
    std::cout << *next_it << "\n"; 

    // it_40 is now invalid (UB if dereferenced or used)
    // std::cout << *it_40 << "\n"; 

    return 0;
}
